async function submitQuiz(event){if(event.target.id!=='quiz-form')return;event.preventDefault();if(!state.user?.registered){showDialog('signup');return}const item=study(state.selected),form=new FormData(event.target),answers=item.quiz.map((_,index)=>Number(form.get(`question-${index}`)));if(item.quiz.some((_,index)=>form.get(`question-${index}`)===null)){toast(item.quiz.length===1?'Answer the question first.':'Answer every question first.');return}const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const result=await api('/study/quiz','POST',{study_id:item.id,answers});state.progress=state.progress.filter(row=>row.study_id!==item.id).concat({...progress(item.id),study_id:item.id,quiz_score:result.score});$('#quiz-result').innerHTML=`<div class="quiz-result"><strong>${result.score} of ${result.total} correct</strong>${result.explanations.map((explanation,index)=>`<p>${result.correct[index]?'✓':'✗'} ${esc(explanation)}</p>`).join('')}</div>`;toast('Your result was saved.')}catch(error){toast(error.message)}finally{button.disabled=false}}
