/* Online friends (friends API on Cloudflare Workers + KV) */
const MSB_FRIENDS_KEY='msb_friends_id',MSB_FRIENDS_LIST_KEY='msb_friends_list',MSB_FRIEND_REQUESTS_KEY='msb_friend_requests';
const MSB_SHOWS=['jeopardy','millionaire','feud','sound','babel','defend','doctrine'];
const MSB_SHOW_LABEL={jeopardy:'Jeopardy',millionaire:'Millionaire',feud:'Family Feud',sound:'Sound It Out',babel:'Tower of Babel',defend:'Defend the Faith',doctrine:'Say It Right'};
function msbFriendsId(){try{const v=JSON.parse(localStorage.getItem(MSB_FRIENDS_KEY));return v&&v.code&&v.secret?v:null}catch{return null}}
function msbPublicStats(stats){const src=stats&&typeof stats==='object'&&!Array.isArray(stats)?stats:{};const bests={},levels={};for(const show of MSB_SHOWS){bests[show]=Number(src.bests&&src.bests[show])||0;levels[show]=Number(src.levels&&src.levels[show])||0}return{bests,levels,studies:Math.max(0,Math.floor(Number(src.studies)||0))}}
function msbFriendRecord(friend){if(!friend||typeof friend!=='object'||Array.isArray(friend))return null;const extra=friend.profile&&typeof friend.profile==='object'&&!Array.isArray(friend.profile)?friend.profile:{};const text=key=>{const a=typeof friend[key]==='string'?friend[key].trim():'';const b=typeof extra[key]==='string'?extra[key].trim():'';return a||b};const code=typeof friend.code==='string'?friend.code.trim():'';if(!code)return null;const view={code,name:typeof friend.name==='string'?friend.name.trim():'',updatedAt:Number(friend.updatedAt)||0,unread:Math.max(0,Math.floor(Number(friend.unread)||0)),stats:msbPublicStats(friend.stats)};const profile={};for(const key of ['handle','city','bio']){const value=text(key);if(value){view[key]=value;profile[key]=value}}for(const key of ['avatar_data','cover_data']){const value=msbPublicImage(friend[key])||msbPublicImage(extra[key]);if(value){view[key]=value;profile[key]=value}}if(Object.keys(profile).length)view.profile=profile;return view}
function msbFriendsCached(){try{const raw=JSON.parse(localStorage.getItem(MSB_FRIENDS_LIST_KEY));const rows=Array.isArray(raw)?raw.map(msbFriendRecord).filter(Boolean):[];const next=JSON.stringify(rows);if(JSON.stringify(raw)!==next){try{localStorage.setItem(MSB_FRIENDS_LIST_KEY,next)}catch{}}return rows}catch{try{localStorage.removeItem(MSB_FRIENDS_LIST_KEY)}catch{}return[]}}
function msbFriendsStats(){const store=msbStore();let prog={};try{prog=JSON.parse(localStorage.getItem('msb_gx_progress'))||{}}catch{}const levels={},bests={};for(const show of MSB_SHOWS){levels[show]=Array.isArray(prog[show]?.done)?prog[show].done.length:0;bests[show]=0}return{bests,levels,studies:store.progress.filter(row=>row.completed_at).length}}
async function msbFriendsCall(path,body){const res=await fetch(MSB_FRIENDS_API+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});let data=null;try{data=await res.json()}catch{}if(!res.ok){const failure=Error((data&&data.error)||'The friends server did not answer.');failure.status=res.status;throw failure}return data}
function msbPublicImage(value){const raw=String(value??'').trim();if(/^data:image\/(?:jpeg|png|webp);base64,[a-z0-9+/]+={0,2}$/i.test(raw))return raw;if(/^https:\/\/[^\s"'<>]+$/i.test(raw))return raw;return ''}
function msbFriendsPublicProfile(){const p=msbStore().profile||{},profile={};for(const key of ['handle','city','bio'])if(typeof p[key]==='string'&&p[key].trim())profile[key]=p[key].trim();const avatar=msbPublicImage(p.avatar_data),cover=msbPublicImage(p.cover_data);if(avatar)profile.avatar_data=avatar;if(cover)profile.cover_data=cover;return profile}
async function msbFriendsSync(){const id=msbFriendsId();if(!id)return;const profile=msbFriendsPublicProfile(),body={code:id.code,secret:id.secret,stats:msbFriendsStats()};const name=typeof id.name==='string'?id.name.trim():'';if(name)body.name=name;for(const key of ['handle','city','bio','avatar_data','cover_data'])if(profile[key])body[key]=profile[key];body.avatar_saint='';if(!profile.avatar_data)body.avatar_data='';if(Object.keys(profile).length)body.profile=profile;const synced=await msbFriendsCall('/sync',body);if(synced&&typeof synced.publicId==='string'&&synced.publicId){id.publicId=synced.publicId;try{localStorage.setItem(MSB_FRIENDS_KEY,JSON.stringify(id))}catch{}}}
function msbSocial(){const wrap=fn=>async(...args)=>{const id=msbFriendsId();if(!id)throw Error('Get your friend code first (Profile → Friends), then come back.');return fn(id,...args)};return{
  identity:()=>{const id=msbFriendsId();return id?{code:id.code,name:msbStore().profile?.name||id.name||'Friend',publicId:typeof id.publicId==='string'?id.publicId:''}:null},
  submitScore:wrap((id,show,score,level)=>msbFriendsCall('/scores/submit',{code:id.code,secret:id.secret,show,score,level})),
  createRoom:wrap((id,show,level)=>msbFriendsCall('/room/create',{code:id.code,secret:id.secret,show,level})),
  joinRoom:wrap((id,room)=>msbFriendsCall('/room/join',{code:id.code,secret:id.secret,room})),
  roomStart:wrap((id,room)=>msbFriendsCall('/room/start',{code:id.code,secret:id.secret,room})),
  roomScore:wrap((id,room,score,finished)=>msbFriendsCall('/room/score',{code:id.code,secret:id.secret,room,score,finished})),
  roomState:wrap((id,room)=>msbFriendsCall('/room/state',{code:id.code,secret:id.secret,room})),
  roomLeave:wrap((id,room)=>msbFriendsCall('/room/leave',{code:id.code,secret:id.secret,room})),
  publicScores:async show=>{const res=await fetch(MSB_FRIENDS_API+'/scores?show='+encodeURIComponent(show));let data=null;try{data=await res.json()}catch{}if(!res.ok)throw Error((data&&data.error)||'Public scores are unavailable right now.');return ((data&&data.scores)||[]).map(row=>{if(!row||typeof row!=='object')return null;return {id:typeof row.id==='string'?row.id:'',name:typeof row.name==='string'?row.name:'',score:Number(row.score)||0,level:Number(row.level)||0,ts:Number(row.ts)||0}}).filter(Boolean)},
}}
async function msbFriendsFetch(){const id=msbFriendsId();if(!id)return msbFriendsCached();const list=await msbFriendsCall('/friends',{code:id.code,secret:id.secret});const rows=Array.isArray(list)?list.map(msbFriendRecord).filter(Boolean):[];try{localStorage.setItem(MSB_FRIENDS_LIST_KEY,JSON.stringify(rows))}catch{}return rows}
function msbFriendsAgo(ts){const s=Math.max(0,(Date.now()-(ts||0))/1000);if(s<90)return'active just now';if(s<5400)return`active ${Math.round(s/60)}m ago`;if(s<172800)return`active ${Math.round(s/3600)}h ago`;return`active ${Math.round(s/86400)}d ago`}
function msbFriendsChips(f){const st=f.stats||{bests:{},levels:{},studies:0};const studies=Math.max(0,Math.floor(Number(st.studies))||0);const chips=[`<span class="friend-chip">📖 ${studies} ${studies===1?'study':'studies'}</span>`];for(const show of MSB_SHOWS){const lv=st.levels?.[show]||0;if(lv>0)chips.push(`<span class="friend-chip">${MSB_SHOW_LABEL[show]} · Lv ${lv}/5</span>`)}return chips.join('')}
function msbFriendSelectHtml(list, selected){const rows=Array.isArray(list)?list:[];if(!rows.length)return '<option value="">No friends yet — add one above</option>';const chosen=selected||'';return rows.map(f=>`<option value="${esc(f.code)}" ${chosen===f.code?'selected':''}>${esc(f.name||'Friend')} (${esc(f.code)})</option>`).join('')}
function msbRefreshFriendPickers(list){for(const id of ['fn-to','sh-to']){const el=$('#'+id);if(!el)continue;el.innerHTML=msbFriendSelectHtml(list, el.value)}}
function msbFriendsListHtml(list){const rows=(Array.isArray(list)?list:[]).slice().sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));if(!rows.length)return'<p class="muted">No friends yet. When a request is accepted, you both appear here. Only you can see this list.</p>';return rows.map(f=>`<div class="card friend-row"><button type="button" class="friend-open" data-action="friend-open" data-code="${esc(f.code||'')}"><strong>${esc(f.name||'Friend')}</strong> <span class="muted">${esc(f.code||'')}</span>${f.unread?`<span class="friend-chip friend-unread">● ${f.unread} new message${f.unread===1?'':'s'}</span>`:''}<br><small class="muted">${msbFriendsAgo(f.updatedAt)}</small><div class="friend-chips">${msbFriendsChips(f)}</div></button><div class="friend-row-btns"><button class="secondary" data-action="msg-open" data-code="${esc(f.code||'')}" data-name="${esc(f.name||'Friend')}">💬 Message</button><button class="secondary" data-action="friends-remove" data-code="${esc(f.code||'')}">Remove</button></div></div>`).join('')}
function msbFriendRequestsCached(){try{const raw=JSON.parse(localStorage.getItem(MSB_FRIEND_REQUESTS_KEY));const incoming=Array.isArray(raw?.incoming)?raw.incoming:[];const outgoing=Array.isArray(raw?.outgoing)?raw.outgoing:[];return {incoming,outgoing,supported:raw?.supported!==false}}catch{return {incoming:[],outgoing:[],supported:true}}}
function msbFriendRequestRows(rows,incoming){return (Array.isArray(rows)?rows:[]).map(row=>{const name=esc(row?.name||'Friend');if(incoming)return `<div class="card friend-row"><div><strong>${name}</strong><br><small class="muted">Wants to be friends</small></div><div class="friend-row-btns"><button class="primary" data-action="friends-accept" data-code="${esc(row?.code||'')}">Accept</button><button class="secondary" data-action="friends-decline" data-code="${esc(row?.code||'')}">Decline</button></div></div>`;return `<div class="card friend-row"><div><strong>${name}</strong><br><small class="muted">Waiting for them to accept</small></div></div>`}).join('')}
function msbFriendRequestsHtml(box){if(box&&box.supported===false)return '<p class="muted">Friend requests appear here once the friends server is updated. Until then, sending a code still connects you right away.</p>';const incoming=msbFriendRequestRows(box?.incoming,true),outgoing=msbFriendRequestRows(box?.outgoing,false);if(!incoming&&!outgoing)return '<p class="muted">No pending requests.</p>';return `${incoming}${outgoing}`}
function msbPaintRequests(box){const el=$('#friends-requests');if(el)el.innerHTML=msbFriendRequestsHtml(box||msbFriendRequestsCached())}
async function msbFriendRequestsFetch(){const id=msbFriendsId();if(!id)return {incoming:[],outgoing:[],supported:false};try{const box=await msbFriendsCall('/friend/requests',{code:id.code,secret:id.secret});const next={incoming:Array.isArray(box?.incoming)?box.incoming:[],outgoing:Array.isArray(box?.outgoing)?box.outgoing:[],supported:true};try{localStorage.setItem(MSB_FRIEND_REQUESTS_KEY,JSON.stringify(next))}catch{}return next}catch(error){if(error&&(error.status===404||error.status===400))return {incoming:[],outgoing:[],supported:false};throw error}}
function friendText(record,key){const extra=record&&record.profile&&typeof record.profile==='object'?record.profile:null;const value=record&&typeof record[key]==='string'?record[key]:extra&&typeof extra[key]==='string'?extra[key]:'';return String(value||'').trim()}
function friendImage(record,...keys){const extra=record&&record.profile&&typeof record.profile==='object'?record.profile:null;for(const key of keys){const src=safeImageSrc(record&&record[key])||safeImageSrc(extra&&extra[key]);if(src)return src}return ''}
function friendProfileScreen(code){const f=(msbFriendsCached()||[]).find(item=>item&&item.code===code);if(!f){toast('That friend is not in the list on this device.');openFriends();return}state.screen='friend';state.friendCode=code;document.querySelectorAll('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav==='profile'));const name=friendText(f,'name')||'Friend',handle=friendText(f,'handle'),city=friendText(f,'city'),bio=friendText(f,'bio'),avatar=friendImage(f,'avatar_data','avatar','avatarUrl'),cover=friendImage(f,'cover_data','cover','coverUrl');screen.innerHTML=`<button class="text-button back" data-action="friends">← Friends</button><span class="eyebrow">FRIEND</span><div class="profile-cover">${cover?`<img src="${cover}" alt="">`:''}</div><div class="profile-head"><div class="profile-avatar friend-profile-avatar">${avatar?`<img src="${avatar}" alt="">`:esc(name[0]||'F')}</div><div><h1>${esc(name)}</h1>${handle?`<p>@${esc(handle)}</p>`:''}${city?`<p class="muted">${esc(city)}</p>`:''}</div></div>${bio?`<p class="lead">${esc(bio)}</p>`:''}<p class="muted">Friend code ${esc(f.code||'')}. ${msbFriendsAgo(f.updatedAt)}.</p><div class="friend-chips">${msbFriendsChips(f)}</div><p><button class="secondary" data-action="msg-open" data-code="${esc(f.code||'')}" data-name="${esc(name)}">Message</button> <button class="secondary" data-action="friends">Back to friends</button></p>`;window.scrollTo({top:0,behavior:'auto'})}
function friendsScreen(){const id=msbFriendsId(),p=msbStore().profile||{};if(!id){screen.innerHTML=`<span class="eyebrow">FRIENDS</span><h1>Study and play together</h1><p class="lead">Get a friend code and share it. The other person sends a request, and you accept it before you are friends. You will see each other's studies finished and game levels beaten. Your notes stay private unless you choose to send one to a friend. Only you can see your friends list.</p><section class="card"><p><label for="friends-name">Your name for friends</label></p><p><input id="friends-name" class="text-input" type="text" value="${esc(p.name||'Friend')}" maxlength="40" autocomplete="nickname"></p><button class="primary" data-action="friends-register">Get my friend code</button><p class="muted">Works only with an internet connection; everything else in the app still works offline.</p></section><p><button class="secondary" data-nav="profile">Back to profile</button></p>`;return}let draft=null;try{draft=JSON.parse(localStorage.getItem(MSB_NOTE_DRAFT_KEY))}catch{}const friends=msbFriendsCached();const friendOpts=msbFriendSelectHtml(friends, draft&&draft.to);const studyOpts=['<option value="">No study attached</option>'].concat((Array.isArray(state.studies)?state.studies:[]).map(s=>`<option value="${esc(s.id)}" ${draft&&draft.studyId===s.id?'selected':''}>${esc(s.title)} — ${esc(s.reference)}</option>`)).join('');const banner=draft&&draft.body?`<p class="muted">📝 Carrying your note from “${esc(draft.title||'a study')}” — it is already in the box below. <button class="secondary" data-action="friends-draft-clear">Discard draft</button></p>`:'';screen.innerHTML=`<span class="eyebrow">FRIENDS</span><h1>Your friend code</h1><section class="card"><p class="friend-code">${esc(id.code)}</p><p class="muted">Share this code with someone you want to study with. They send a request, and you accept it here before you are friends. A private secret is stored in this browser and sent to the friends server with your requests so it can recognize you. It is not shown here, and it is not your study password. Only you can see your friends list.</p><p><button class="primary" data-action="friends-copy">Copy code</button> <button class="secondary" data-action="friends-share">Share</button></p></section><section class="card"><span class="eyebrow">SEND A REQUEST</span><p><label for="friends-add-code">Their friend code</label></p><p><input id="friends-add-code" class="text-input" type="text" placeholder="MSB-XXXXXX" autocapitalize="characters" autocomplete="off"></p><button class="primary" data-action="friends-add">Send request</button></section><h2>Requests</h2><div id="friends-requests">${msbFriendRequestsHtml(msbFriendRequestsCached())}</div><h2>Friends <button class="secondary" data-action="friends-refresh">Refresh</button></h2><div id="friends-list">${msbFriendsListHtml(msbFriendsCached())}</div><section class="card"><span class="eyebrow">SEND A NOTE TO A FRIEND</span><p class="muted">Only the note you write here is sent — your journal itself stays private on your device. Attach the study and its verse travels with the note: your friend can open the passage in the Bible and save the note straight into their own journal.</p>${banner}<p><select id="fn-to" class="text-input">${friendOpts}</select></p><p><select id="fn-study" class="text-input">${studyOpts}</select></p><p><input id="fn-title" class="text-input" type="text" maxlength="120" placeholder="Title (optional)" value="${esc(draft?.title||'')}"></p><p><textarea id="fn-body" class="note-field" maxlength="4000" rows="4" placeholder="Encouragement, a question, what the passage showed you…">${esc(draft?.body||'')}</textarea></p><button class="primary" data-action="friends-note-send">Send note</button></section><section class="card"><span class="eyebrow">SHARED NOTES — MAKE THEM TOGETHER</span><p class="muted">Start a note with a friend and you can both keep writing it. Every edit shows who made it. Attach the study and its verse travels with the note, and either of you can save a copy onto that verse in your own Bible.</p><p><select id="sh-to" class="text-input">${friendOpts}</select></p><p><select id="sh-study" class="text-input">${studyOpts}</select></p><p><input id="sh-title" class="text-input" type="text" maxlength="120" placeholder="Title (optional)"></p><p><textarea id="sh-body" class="note-field" maxlength="4000" rows="3" placeholder="Start the note together…"></textarea></p><button class="primary" data-action="shared-create">Start a shared note</button></section><h2>Shared with you</h2><div id="friends-shared">${msbSharedHtml(msbSharedCached())}</div><h2>Notes from friends</h2><div id="friends-notes">${msbFriendsNotesHtml(msbFriendsNotesCached())}</div><p><button class="secondary" data-nav="profile">Back to profile</button></p>`}
function openFriends(){msbStopMsgPoll();if(state.screen==='bible')BibleReader.hide();if(window.BibleGames)BibleGames.hide();state.screen='friends';document.querySelectorAll('[data-nav]').forEach(button=>button.classList.toggle('active',button.dataset.nav==='profile'));friendsScreen();window.scrollTo({top:0,behavior:'auto'});msbFriendsSync().catch(()=>{});msbFriendsFetch().then(list=>{const el=$('#friends-list');if(el)el.innerHTML=msbFriendsListHtml(list);msbRefreshFriendPickers(list)}).catch(()=>{});msbFriendRequestsFetch().then(box=>msbPaintRequests(box)).catch(()=>{});msbFriendsNotesFetch().then(b=>msbRenderNotes(b)).catch(()=>{});msbSharedFetch().then(()=>{const el=$('#friends-shared');if(el)el.innerHTML=msbSharedHtml(msbSharedCached())}).catch(()=>{})}
const MSB_FRIENDS_NOTES_KEY='msb_friends_notes',MSB_NOTE_DRAFT_KEY='msb_note_draft';
function msbFriendsNotesCached(){try{const v=JSON.parse(localStorage.getItem(MSB_FRIENDS_NOTES_KEY));return v&&Array.isArray(v.inbox)?v:{inbox:[],sent:[]}}catch{return{inbox:[],sent:[]}}}
async function msbFriendsNotesFetch(){const id=msbFriendsId();if(!id)return msbFriendsNotesCached();const box=await msbFriendsCall('/notes',{code:id.code,secret:id.secret});try{localStorage.setItem(MSB_FRIENDS_NOTES_KEY,JSON.stringify(box))}catch{}return box}
let msbBibleIndexPromise=null;
function msbBibleIndex(){if(!msbBibleIndexPromise)msbBibleIndexPromise=fetch('bible/index.json').then(r=>r.json()).catch(()=>null);return msbBibleIndexPromise}
async function msbRefTarget(reference){const text=String(reference||'').split(';')[0].trim();const m=text.match(/^(.+?)\s+(\d+)(?:\((\d+)\))?(?::(\d+))?/);if(!m)return null;const idx=await msbBibleIndex();if(!idx||!Array.isArray(idx.books))return null;const want=m[1].trim().toLowerCase();const book=idx.books.find(b=>b.name.toLowerCase()===want)||idx.books.find(b=>b.name.toLowerCase()===want+'s')||idx.books.find(b=>b.name.toLowerCase()===want.replace(/s$/,''));if(!book)return null;const paren=m[3]?Number(m[3]):0,leading=Number(m[2]);const chapter=/^psalms?$/.test(want)&&paren?paren:leading;const start=book.chapterStart||1;if(!Number.isInteger(chapter)||chapter<start||chapter>book.chapters)return null;return{book:book.id,chapter,verse:m[4]?Number(m[4]):0,label:text}}
function msbNoteWhen(ts){const d=new Date(ts||0);if(isNaN(d))return'';return d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+' · '+d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}
function msbNoteCard(n,box){const mine=box==='sent';const friendName=code=>(msbFriendsCached().find(f=>f.code===code)||{}).name||code||'';const head=mine?('To '+esc(friendName(n.to))):('From '+esc(n.fromName||friendName(n.from)||'Friend'));const item=n.studyId?study(n.studyId):null;return `<div class="card friend-note${!mine&&!n.read?' friend-note-new':''}"><div class="friend-note-head"><strong>${esc(n.title||(item?item.title:'A note'))}</strong>${!mine&&!n.read?'<span class="friend-chip">● New</span>':''}</div><small class="muted">${head} · ${msbNoteWhen(n.ts)}</small>${n.ref&&n.ref.label?`<p><span class="friend-chip">📖 ${esc(n.ref.label)}</span></p>`:''}<p class="friend-note-body">${esc(n.body||'')}</p><div class="note-actions">${n.ref&&n.ref.book?`<button class="secondary" data-action="friends-note-verse" data-id="${esc(n.id)}" data-book="${n.ref.book}" data-chapter="${n.ref.chapter}" data-verse="${n.ref.verse||''}">Open the verse</button>`:''}${!mine&&n.ref&&n.ref.verse?`<button class="secondary" data-action="friends-note-verse-save" data-id="${esc(n.id)}">Save to the verse &amp; edit</button>`:''}${item?`<button class="secondary" data-lesson="${esc(item.id)}">Open the study</button>`:''}${!mine?`<button class="secondary" data-action="friends-note-save" data-id="${esc(n.id)}">Save to my notes</button><button class="secondary" data-action="friends-note-reply" data-id="${esc(n.id)}">Reply</button>`:''}<button class="secondary" data-action="friends-note-del" data-id="${esc(n.id)}" data-box="${box}">Delete</button></div></div>`}
function msbFriendsNotesHtml(box){const b=box||msbFriendsNotesCached();const inbox=Array.isArray(b.inbox)?b.inbox:[],sent=Array.isArray(b.sent)?b.sent:[];return `${inbox.length?inbox.map(n=>msbNoteCard(n,'inbox')).join(''):'<p class="muted">No notes yet. When a friend sends you one, it lands here — with its verse and study attached.</p>'}${sent.length?`<h3>Sent by you</h3>${sent.map(n=>msbNoteCard(n,'sent')).join('')}`:''}`}
function msbRenderNotes(box){const el=$('#friends-notes');if(el)el.innerHTML=msbFriendsNotesHtml(box||msbFriendsNotesCached())}
function msbNoteMarkRead(id){const me=msbFriendsId();if(!me||!id)return;msbFriendsCall('/note/read',{code:me.code,secret:me.secret,id}).catch(()=>{})}
function msbNoteFind(id){const b=msbFriendsNotesCached();return (b.inbox||[]).find(n=>n.id===id)||(b.sent||[]).find(n=>n.id===id)||null}
const MSB_SHARED_KEY='msb_friends_shared';
/* ---------- Achievements (Xbox-style unlocks, stored on this device) ---------- */
const MSB_ACHIEVEMENTS=[
  {id:'first-chapter',icon:'🌱',name:'First Steps',desc:'Log your first chapter as read.',points:10},
  {id:'chapters-10',icon:'📖',name:'Faithful Reader',desc:'Log 10 chapters as read.',points:25},
  {id:'chapters-50',icon:'🔥',name:'Deep in the Word',desc:'Log 50 chapters as read.',points:50},
  {id:'chapters-100',icon:'💯',name:'Hundredfold',desc:'Log 100 chapters as read.',points:100},
  {id:'chapters-250',icon:'🪔',name:'Lamp to My Feet',desc:'Log 250 chapters as read.',points:150},
  {id:'psalms-25',icon:'🎵',name:'Psalm Singer',desc:'Log 25 chapters of Psalms.',points:50},
  {id:'psalms-all',icon:'📜',name:'Through the Psalter',desc:'Log every chapter of Psalms.',points:200},
  {id:'gospels-all',icon:'✝️',name:'Gospel Witness',desc:'Log all four Gospels, cover to cover.',points:150},
  {id:'nt-all',icon:'🕊️',name:'New Testament Complete',desc:'Log the whole New Testament.',points:250},
  {id:'bible-all',icon:'👑',name:'The Whole Counsel of God',desc:'Log every chapter of the Bible.',points:500},
  {id:'studies-1',icon:'🎓',name:'Student of the Word',desc:'Complete your first study.',points:25},
  {id:'studies-all',icon:'🛤️',name:'Reading Path Complete',desc:'Complete every study on the path.',points:100},
  {id:'streak-7',icon:'📆',name:'Seven Days in the Word',desc:'Read or complete a study 7 days in a row.',points:75},
  {id:'notes-1',icon:'✍️',name:'First Journal Note',desc:'Write your first study note.',points:15},
  {id:'verse-notes-1',icon:'✎',name:'Verse Keeper',desc:'Save a note onto a Bible verse.',points:25},
  {id:'highlights-1',icon:'🖍️',name:'First Highlight',desc:'Highlight your first verse.',points:10},
  {id:'friend-1',icon:'🤝',name:'Iron Sharpens Iron',desc:'Get your friend code and join the friends circle.',points:25},
];
async function msbAchievementsCompute(){
  const store=msbStore(),idx=await msbBibleIndex().catch(()=>null),books=idx&&Array.isArray(idx.books)?idx.books:[];
  const bookTotal=b=>b?b.chapters-(b.chapterStart||1)+1:0;
  const perBook={};for(const l of store.readLog||[])perBook[l.book_id]=(perBook[l.book_id]||0)+1;
  const sumBooks=ids=>ids.reduce((n,id)=>n+(perBook[id]||0),0);
  const totalBooks=ids=>ids.reduce((n,id)=>n+bookTotal(books[id-1]),0);
  const gospelIds=[40,41,42,43],ntIds=Array.from({length:27},(_,i)=>40+i),allIds=books.map(b=>b.id);
  /* A book counts only when every chapter in it is logged — Matthew 1 alone
     is not "the Gospel read". Book achievements count finished books. */
  const booksFinished=ids=>ids.filter(id=>{const t=bookTotal(books[id-1]);return t>0&&(perBook[id]||0)>=t}).length;
  const studiesTotal=Array.isArray(state.studies)&&state.studies.length?state.studies.length:6;
  const days=new Set();
  for(const l of store.readLog||[])if(l.ts)days.add(new Date(l.ts*1000).toDateString());
  for(const p of store.progress||[])if(p.completed_at)days.add(new Date(p.completed_at*1000).toDateString());
  let streak=0;const day=new Date();day.setHours(0,0,0,0);if(!days.has(day.toDateString()))day.setDate(day.getDate()-1);
  while(days.has(day.toDateString())){streak++;day.setDate(day.getDate()-1)}
  const cur={
    'first-chapter':(store.readLog||[]).length,'chapters-10':(store.readLog||[]).length,'chapters-50':(store.readLog||[]).length,'chapters-100':(store.readLog||[]).length,'chapters-250':(store.readLog||[]).length,
    'psalms-25':perBook[19]||0,'psalms-all':[perBook[19]||0,bookTotal(books[18])||150],
    'gospels-all':[booksFinished(gospelIds),4],'nt-all':[booksFinished(ntIds),27],'bible-all':[booksFinished(allIds),books.length||78],
    'studies-1':(store.progress||[]).filter(p=>p.completed_at).length,'studies-all':[(store.progress||[]).filter(p=>p.completed_at).length,studiesTotal],
    'streak-7':streak,'notes-1':(store.notes||[]).filter(n=>(n.body||'').trim()).length,'verse-notes-1':(store.verseNotes||[]).length,'highlights-1':(store.highlights||[]).length,'friend-1':msbFriendsId()?1:0,
  };
  const targets={'first-chapter':1,'chapters-10':10,'chapters-50':50,'chapters-100':100,'chapters-250':250,'psalms-25':25,'streak-7':7,'notes-1':1,'verse-notes-1':1,'highlights-1':1,'friend-1':1};
  return MSB_ACHIEVEMENTS.map(a=>{const raw=cur[a.id];const current=Array.isArray(raw)?raw[0]:raw||0;const target=Array.isArray(raw)?raw[1]:targets[a.id]||1;return{...a,current:Math.min(current,target),target,unlocked:current>=target,unlockedAt:(store.achievements||{})[a.id]||null}});
}
async function msbAchievementsCheck(){
  /* Achievements sit on the real counter: unlocked state is recomputed from
     the live numbers every check. Un-log a chapter (or un-finish a study)
     below a threshold and the achievement locks again, score included. */
  const store=msbStore();const prev=store.achievements||{};
  const raw=await msbAchievementsCompute();const newly=[];const next={};
  for(const a of raw){
    if(a.unlocked){next[a.id]=prev[a.id]||Math.floor(Date.now()/1000);if(!prev[a.id])newly.push(a)}
  }
  store.achievements=next;msbSave(store);
  const list=raw.map(a=>({...a,unlocked:!!next[a.id],unlockedAt:next[a.id]||null}));
  return{list,newly,score:list.filter(a=>a.unlockedAt).reduce((n,a)=>n+a.points,0)};
}
function showAchievement(a){
  const pop=document.createElement('div');pop.className='ach-pop';pop.setAttribute('role','status');
  pop.innerHTML=`<span class="ach-pop-icon">${esc(a.icon||'🏆')}</span><span class="ach-pop-body"><small>ACHIEVEMENT UNLOCKED</small><strong>${esc(a.name)}</strong><span>${esc(a.desc)}</span></span><span class="ach-pop-points">✦ ${a.points}</span>`;
  document.body.appendChild(pop);
  requestAnimationFrame(()=>pop.classList.add('ach-pop-in'));
  setTimeout(()=>{pop.classList.remove('ach-pop-in');pop.classList.add('ach-pop-out')},4200);
  setTimeout(()=>pop.remove(),4800);
}
function msbSpeak(sayText,term){try{const synth=window.speechSynthesis;if(!synth||typeof SpeechSynthesisUtterance==='undefined')return false;synth.cancel();const slow=new SpeechSynthesisUtterance(sayText);slow.rate=.72;const word=new SpeechSynthesisUtterance(term);word.rate=.85;const release=()=>{if(synth.speaking)return;if(window.msbYieldAudio)window.msbYieldAudio('speech',false)};slow.onend=slow.onerror=release;word.onend=word.onerror=release;if(window.msbYieldAudio)window.msbYieldAudio('speech',true);synth.speak(slow);synth.speak(word);return true}catch(e){return false}}
function msbWordChips(item){if(!item?.words?.length)return'';return `<div class="word-chips" role="group" aria-label="Hear the words of this lesson"><span class="word-chips-label">Hear the words</span>${item.words.map((w,i)=>`<button type="button" class="word-chip" data-say="${i}" aria-label="Hear how to say ${esc(w.term)}">🔊 ${esc(w.term)}</button>`).join('')}</div>`}
function hearWord(event){const b=event.target.closest('[data-say]');if(!b||state.screen!=='mini')return;const item=state.challenges.find(e=>e.id===state.selected);const w=item?.words?.[Number(b.dataset.say)];if(!w)return;if(!msbSpeak(w.say||w.term,w.term))toast('Voice is not available on this device.')}
async function msbCelebrate(){try{const r=await api('/bible/achievements/check','POST',{});(r.newly||[]).forEach((a,i)=>setTimeout(()=>showAchievement(a),i*500));return r}catch{return null}}
async function achievementsScreen(){
  state.screen='achievements';
  screen.innerHTML=`<span class="eyebrow">ACHIEVEMENTS</span><h1>🏆 Your achievements</h1><div class="loading">Counting the victories…</div>`;
  let r=null;try{r=await api('/bible/achievements/check','POST',{})}catch{}
  if(state.screen!=='achievements')return;
  const list=r&&Array.isArray(r.list)?r.list:[];
  const unlocked=list.filter(a=>a.unlockedAt);
  const cards=list.map(a=>`<div class="card ach-card ${a.unlockedAt?'ach-unlocked':'ach-locked'}"><span class="ach-icon">${esc(a.icon||'🏆')}</span><div class="ach-main"><strong>${esc(a.name)}</strong><p class="small muted">${esc(a.desc)}</p><div class="ach-bar"><i style="width:${a.target?Math.round(a.current/a.target*100):0}%"></i></div><small class="muted">${a.unlockedAt?('Unlocked '+new Date(a.unlockedAt*1000).toLocaleDateString()):(a.current+' / '+a.target)}</small></div><span class="ach-points">✦ ${a.points}</span></div>`).join('');
  screen.innerHTML=`<span class="eyebrow">ACHIEVEMENTS</span><h1>🏆 Your achievements</h1><p class="lead">Score <strong>✦ ${r?r.score:0}</strong> · ${unlocked.length} of ${list.length} unlocked. Reading, studying, noting, and friends all count.</p>${cards||'<p class="muted">Achievements are unavailable right now.</p>'}<p><button class="secondary" data-nav="profile">Back to profile</button></p>`;
  window.scrollTo({top:0,behavior:'auto'});
}

function msbSharedCached(){try{const v=JSON.parse(localStorage.getItem(MSB_SHARED_KEY));return Array.isArray(v)?v:[]}catch{return[]}}
async function msbSharedFetch(){const id=msbFriendsId();if(!id)return msbSharedCached();const res=await msbFriendsCall('/shared/list',{code:id.code,secret:id.secret});const notes=Array.isArray(res.notes)?res.notes:[];try{localStorage.setItem(MSB_SHARED_KEY,JSON.stringify(notes))}catch{}return notes}
function msbSharedCard(n){const me=msbFriendsId();const partner=me&&n.owner===me.code?(n.withName||'Friend'):(n.ownerName||'Friend');return `<div class="card friend-note"><div class="friend-note-head"><strong>${esc(n.title||'Shared note')}</strong><span class="friend-chip">together with ${esc(partner||'Friend')}</span></div><small class="muted">Last edit by ${esc(n.updatedByName||'')} · ${msbNoteWhen(n.updatedAt)}</small>${n.ref&&n.ref.label?`<p><span class="friend-chip">📖 ${esc(n.ref.label)}</span></p>`:''}<p class="friend-note-body">${esc((n.body||'').slice(0,240))}${(n.body||'').length>240?'…':''}</p><div class="note-actions"><button class="secondary" data-action="shared-open" data-id="${esc(n.id)}">Open &amp; write together</button>${n.ref&&n.ref.book?`<button class="secondary" data-action="shared-verse" data-id="${esc(n.id)}">Save to the verse &amp; edit</button>`:''}<button class="secondary" data-action="shared-del" data-id="${esc(n.id)}">Delete for both</button></div></div>`}
function msbSharedHtml(list){const rows=Array.isArray(list)?list:[];return rows.length?rows.map(msbSharedCard).join(''):'<p class="muted">No shared notes yet. Start one above and you can both keep writing it.</p>'}
function msbFindShared(id){return msbSharedCached().find(n=>n.id===id)||null}
function openSharedEditor(id){const n=msbFindShared(id);if(!n){toast('That shared note is gone.');return}const me=msbFriendsId();const partner=me&&n.owner===me.code?(n.withName||'Friend'):(n.ownerName||'Friend');state.screen='shared';screen.innerHTML=`<span class="eyebrow">SHARED NOTE</span><h1>${esc(n.title||'Shared note')}</h1><p class="muted">You and ${esc(partner||'your friend')} are both writing this note. Saves go to both of you, and the last edit shows who made it.</p>${n.ref&&n.ref.label?`<p><span class="friend-chip">📖 ${esc(n.ref.label)}</span></p>`:''}<section class="card"><p><input id="shared-title" class="text-input" type="text" maxlength="120" value="${esc(n.title||'')}" placeholder="Title"></p><p><textarea id="shared-body" class="note-field" maxlength="4000" rows="10">${esc(n.body||'')}</textarea></p><small class="muted">Last edit by ${esc(n.updatedByName||'')} · ${msbNoteWhen(n.updatedAt)}</small><div class="note-actions"><button class="primary" data-action="shared-save" data-id="${esc(n.id)}">Save — your friend sees it</button>${n.ref&&n.ref.book?`<button class="secondary" data-action="shared-verse" data-id="${esc(n.id)}">Save to the verse &amp; edit</button>`:''}<button class="secondary" data-action="shared-del" data-id="${esc(n.id)}">Delete for both</button></div></section><p><button class="secondary" data-action="friends">← Back to friends</button></p>`;window.scrollTo({top:0,behavior:'auto'})}
async function msbSaveToVerse(ref,body,fromName,openIt){if(!ref||!ref.book||!ref.chapter||!ref.verse){toast('That note has no exact verse to save onto.');return false}const store=msbStore();store.verseNotes=store.verseNotes||[];const existing=store.verseNotes.find(v=>v.book_id===ref.book&&v.chapter===ref.chapter&&v.verse===ref.verse);const addition=existing&&existing.body.trim()?existing.body.trim()+'\n\n'+body:body;const result=await api('/bible/verse-note','POST',{book_id:ref.book,chapter:ref.chapter,verse:ref.verse,body:addition,from_name:fromName||''});if(result&&Array.isArray(result.verseNotes))BibleReader.applyVerseNotes(result.verseNotes);if(openIt){BibleReader.open(ref.book,ref.chapter,ref.verse);nav('bible')}return result}
let msbMsgTimer=null,msbMsgWith=null;
function msbStopMsgPoll(){if(msbMsgTimer){clearInterval(msbMsgTimer);msbMsgTimer=null}msbMsgWith=null}
function msbThreadHtml(messages,myCode){if(!messages||!messages.length)return'<p class="muted">No messages yet. Say the first word.</p>';return messages.map(m=>`<div class="msg-row ${m.from===myCode?'msg-mine':'msg-theirs'}"><div class="msg-bubble"><p>${esc(m.body||'')}</p><small>${m.from===myCode?'You':esc(m.fromName||'Friend')} · ${msbNoteWhen(m.ts)}</small></div></div>`).join('')}
async function msbLoadThread(code){const id=msbFriendsId();if(!id)return[];const res=await msbFriendsCall('/msg/thread',{code:id.code,secret:id.secret,with:code});return Array.isArray(res.messages)?res.messages:[]}
function openMsgThread(code,name){const id=msbFriendsId();if(!id){toast('Get your friend code first.');return}msbStopMsgPoll();msbMsgWith=code;state.screen='messages';screen.innerHTML=`<span class="eyebrow">MESSAGE</span><h1>${esc(name||'Friend')}</h1><p class="muted">Just between you two. Notes you write together live under Friends → Shared notes.</p><div id="msg-thread" class="msg-thread"><div class="loading">Loading messages…</div></div><section class="card"><p><textarea id="msg-body" class="note-field" maxlength="2000" rows="3" placeholder="Write to ${esc(name||'your friend')}…"></textarea></p><div class="note-actions"><button class="primary" data-action="msg-send" data-code="${esc(code)}">Send message</button><button class="secondary" data-action="friends">← Back to friends</button></div></section>`;window.scrollTo({top:0,behavior:'auto'});const paint=async()=>{if(msbMsgWith!==code||state.screen!=='messages')return;try{const messages=await msbLoadThread(code);const el=$('#msg-thread');if(!el||msbMsgWith!==code)return;const draft=$('#msg-body');const typing=draft&&document.activeElement===draft&&(draft.value||'').length>0;el.innerHTML=msbThreadHtml(messages,id.code);if(!typing)el.scrollTop=el.scrollHeight}catch{}};paint();msbMsgTimer=setInterval(paint,4000)}
window.addEventListener('load',()=>{setTimeout(()=>{msbFriendsSync().catch(()=>{})},2500)});

/* Still Waters — original worship bed. Off until the header speaker is turned on.
   The file is generated by audio/compose.py. See audio/README.md. */
(function msbWorshipBed(){
  const KEY='msb_music', TARGET=0.18, FADE_IN=1.3, FADE_OUT=0.75;
  const button=document.getElementById('music-toggle');
  if(!button)return;
  const holds=new Set();
  let wanted=false, gestured=false, live=false, generation=0, speechAt=0;
  let ctx=null, master=null, buffer=null, bufferPromise=null, sources=[], html=null, htmlFrame=0, arm=null;
  try{wanted=localStorage.getItem(KEY)==='on'}catch{}
  function paint(){
    button.setAttribute('aria-pressed',wanted?'true':'false');
    button.setAttribute('aria-label',wanted?'Turn worship music off':'Turn worship music on');
  }
  paint();
  function bedUrl(){
    const probe=document.createElement('audio');
    const ogg=probe.canPlayType('audio/ogg; codecs="vorbis"');
    return ogg? 'audio/still-waters.ogg' : 'audio/still-waters.mp3';
  }
  function remember(){try{localStorage.setItem(KEY,wanted?'on':'off')}catch{}}
  function unlock(){
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return null;
    if(!ctx){
      ctx=new AC();
      master=ctx.createGain();
      master.gain.value=0;
      master.connect(ctx.destination);
    }
    if(ctx.state==='suspended')ctx.resume();
    return ctx;
  }
  function fadeTo(value,seconds){
    if(!master||!ctx)return;
    const t=ctx.currentTime;
    master.gain.cancelScheduledValues(t);
    master.gain.setValueAtTime(master.gain.value,t);
    master.gain.linearRampToValueAtTime(value,t+Math.max(0.02,seconds));
  }
  function haltSources(){
    sources.forEach(src=>{try{src.stop()}catch{}});
    sources=[];
  }
  function seamless(decoded){
    const sr=decoded.sampleRate, ch0=decoded.getChannelData(0), n=ch0.length;
    let energy=0, samples=0;
    const a=Math.floor(n*0.4), b=Math.floor(n*0.6);
    for(let i=a;i<b;i+=8){energy+=ch0[i]*ch0[i];samples++}
    const gate=Math.sqrt(energy/Math.max(1,samples))*0.15;
    let lead=0; const leadMax=Math.min(n,Math.floor(sr*0.12));
    while(lead<leadMax&&Math.abs(ch0[lead])<gate)lead++;
    let tail=0; const tailMax=Math.min(n-lead-sr,Math.floor(sr*0.12));
    while(tail<tailMax&&Math.abs(ch0[n-1-tail])<gate)tail++;
    const from=lead, to=n-tail, length=to-from;
    const fade=Math.min(Math.floor(sr*0.06),Math.floor(length/8));
    const out=ctx.createBuffer(decoded.numberOfChannels,length,sr);
    for(let c=0;c<decoded.numberOfChannels;c++){
      const src=decoded.getChannelData(c), dst=out.getChannelData(c);
      for(let i=0;i<length;i++)dst[i]=src[from+i];
      for(let i=0;i<fade;i++){
        const t=i/(fade-1);
        const wIn=Math.sin(t*Math.PI/2), wOut=Math.cos(t*Math.PI/2);
        dst[length-fade+i]=wOut*dst[length-fade+i]+wIn*dst[i];
      }
      const ramp=Math.min(128,fade);
      if(ramp>1){
        const join=dst[0];
        const start=length-ramp;
        for(let i=0;i<ramp;i++){
          const w=Math.sin((i/(ramp-1))*Math.PI/2);
          dst[start+i]=(1-w)*dst[start+i]+w*join;
        }
      }
    }
    return out;
  }
  function loadBuffer(){
    if(buffer)return Promise.resolve(buffer);
    if(bufferPromise)return bufferPromise;
    const ac=unlock();
    if(!ac)return Promise.reject(new Error('no-audio'));
    bufferPromise=fetch(bedUrl()).then(res=>{if(!res.ok)throw new Error('load');return res.arrayBuffer()}).then(raw=>ac.decodeAudioData(raw.slice(0))).then(decoded=>{buffer=seamless(decoded);return buffer}).catch(err=>{bufferPromise=null;throw err});
    return bufferPromise;
  }
  function rampHtml(target,seconds){
    if(!html)return;
    cancelAnimationFrame(htmlFrame);
    const from=html.volume, t0=performance.now();
    const step=now=>{
      const k=Math.min(1,(now-t0)/(seconds*1000));
      html.volume=Math.max(0,Math.min(1,from+(target-from)*k));
      if(k<1)htmlFrame=requestAnimationFrame(step);
      else if(target===0&&!live)html.pause();
    };
    htmlFrame=requestAnimationFrame(step);
  }
  function fail(){
    live=false; wanted=false; paint(); remember();
    toast('Worship music could not load.');
  }
  function startFallback(){
    if(!html){
      html=new Audio(bedUrl());
      html.loop=true; html.preload='auto'; html.volume=0; html.dataset.msbBed='1';
    }
    live=true;
    const gen=++generation;
    html.play().then(()=>{
      if(gen!==generation||!live){html.pause();return}
      rampHtml(TARGET,FADE_IN);
    }).catch(()=>{if(gen===generation)fail()});
  }
  function startBed(){
    if(live){
      if(html&&!ctx)rampHtml(TARGET,0.35);
      else fadeTo(TARGET,0.35);
      return;
    }
    gestured=true;
    if(!unlock()){startFallback();return}
    live=true;
    const gen=++generation;
    master.gain.cancelScheduledValues(ctx.currentTime);
    master.gain.setValueAtTime(0,ctx.currentTime);
    loadBuffer().then(buf=>{
      if(gen!==generation||!live)return;
      haltSources();
      const src=ctx.createBufferSource();
      src.buffer=buf; src.loop=true; src.connect(master); src.start();
      sources.push(src);
      fadeTo(TARGET,FADE_IN);
    }).catch(()=>{if(gen===generation)fail()});
  }
  function stopBed(){
    if(!live)return;
    live=false;
    const gen=++generation;
    if(html&&!html.paused)rampHtml(0,FADE_OUT);
    fadeTo(0,FADE_OUT);
    setTimeout(()=>{
      if(generation!==gen)return;
      haltSources();
      if(html)html.pause();
    },FADE_OUT*1000+60);
  }
  function shouldPlay(){return wanted&&gestured&&holds.size===0}
  function sync(){if(shouldPlay())startBed();else stopBed()}
  function yieldAudio(reason,on){
    if(reason==='speech'&&on)speechAt=Date.now();
    const had=holds.has(reason);
    if(on)holds.add(reason);else holds.delete(reason);
    if(had!==holds.has(reason))sync();
  }
  window.msbYieldAudio=yieldAudio;
  function clearArm(){if(arm)document.removeEventListener('pointerdown',arm,true);arm=null}
  function installArm(){
    if(arm||!wanted)return;
    arm=event=>{
      if(event.target&&event.target.closest&&event.target.closest('#music-toggle'))return;
      clearArm();
      gestured=true;
      unlock();
      sync();
    };
    document.addEventListener('pointerdown',arm,true);
  }
  button.addEventListener('click',event=>{
    event.preventDefault();
    event.stopPropagation();
    clearArm();
    wanted=!wanted;
    remember();
    paint();
    gestured=true;
    unlock();
    sync();
  });
  document.addEventListener('visibilitychange',()=>yieldAudio('hidden',document.hidden));
  if(document.hidden)yieldAudio('hidden',true);
  setInterval(()=>{
    const synth=window.speechSynthesis;
    const speaking=!!(synth&&synth.speaking);
    if(speaking)yieldAudio('speech',true);
    else if(Date.now()-speechAt>700)yieldAudio('speech',false);
    const media=Array.from(document.querySelectorAll('audio,video')).some(el=>el.dataset.msbBed!=='1'&&!el.paused&&!el.ended);
    yieldAudio('media',media);
  },400);
  if(wanted)installArm();
})();
